JOIN products p
  ON p.external_id = v.external_id
 AND p.project_id = (SELECT id FROM projects WHERE public_id = '11111111-1111-1111-1111-111111111111'::uuid);

-- 7) Summary
DO $body$
DECLARE pc int; phc int;
BEGIN
  SELECT count(*) INTO pc  FROM products
    WHERE project_id = (SELECT id FROM projects WHERE public_id = '11111111-1111-1111-1111-111111111111'::uuid);
  SELECT count(*) INTO phc FROM product_photos ph
    JOIN products p ON p.id = ph.product_id
    WHERE p.project_id = (SELECT id FROM projects WHERE public_id = '11111111-1111-1111-1111-111111111111'::uuid);
  RAISE NOTICE 'Seed complete: % products, % photos', pc, phc;
END $body$;

COMMIT;
